pub type Task = {
  title: Str;
  done: Bool;
  priority: Int;
} derive[Debug]

fn main() -> Int {
  let t1 = Task{ title: "Write report", done: false, priority: 2 };
  let t2 = Task{ title: "Fix bug", done: false, priority: 5 };
  let t3 = Task{ title: "Refactor", done: true, priority: 1 };
  io.debug(t2);
  return t2.priority;
}
